function rating(){var r=me&&me.rating;$('rating').textContent=r?r.rating:1200;$('record').textContent=r?(r.wins+'W · '+r.losses+'L · '+r.draws+'D · '+r.games+' games'):'0 games';$('identity').textContent=me&&me.x?me.x.display:''}
