function replayCard(){var canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),board=replay?replay.frames[replayAt].board:game.board,size=63,x=68,y=34,moveCount=Math.ceil(game.moves.length/2);canvas.width=1200;canvas.height=630;ctx.fillStyle='#08070a';ctx.fillRect(0,0,1200,630);for(var i=0;i<64;i++){var r=Math.floor(i/8),c=i%8;ctx.fillStyle=(r+c)%2?'#6c596d':'#eadfc8';ctx.fillRect(x+c*size,y+r*size,size,size);if(board[i]!=='.'){ctx.fillStyle=board[i]===board[i].toUpperCase()?'#f8f2e6':'#10253b';ctx.font='48px "DejaVu Sans",sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(pieces[board[i]],x+c*size+size/2,y+r*size+size/2)}}ctx.textAlign='left';ctx.fillStyle='#dfff00';ctx.font='900 38px Arial';ctx.fillText('DASHA VS ANNA',620,130);ctx.fillStyle='#f5eedf';ctx.font='900 30px Arial';ctx.fillText('@'+game.white.handle,620,205);ctx.fillStyle='#72d6ff';ctx.fillText('@'+game.black.handle,620,255);ctx.fillStyle='#ff3b81';ctx.font='900 64px Arial';ctx.fillText(game.result,620,355);ctx.fillStyle='#f5eedf';ctx.font='700 24px Arial';ctx.fillText(game.reason+' · '+moveCount+' move'+(moveCount===1?'':'s'),620,410);ctx.fillStyle='#dfff00';ctx.font='900 25px Arial';ctx.fillText('$dasha · '+(replay?(replayAt?'after '+replayMark(replayAt):'replay start'):'replay every move'),620,535);return canvas}
