/* Opponent moves arrive as a push, not on a timer.
   The lobby socket was already open on this origin carrying chat and no chess at all, so a move
   could take a full poll interval to appear on the other board. The worker now broadcasts a tiny
   {type:'chess', id, version} nudge whenever a game changes; this listens for the one matching the
   game on screen and refetches immediately. The frame is only a trigger — /chess/game stays the
   source of truth, so a stale or forged nudge costs one wasted request and can never move a piece.

   Polling is kept as the floor rather than removed. If the socket is refused (the room enforces an
   80-seat cap and a busy lobby will turn a connection away), or drops mid-game, the game must still
   finish — it just goes back to the old cadence. Socket up: 15s safety net. Socket down: 2.5s.

   Only players connect, and only while their game is live. Every socket counts against the lobby's
   seat cap, so a spectator subscription would let a chess audience crowd out the chat; that needs a
   listener class exempt from the count, which is a change to the capacity model, not to this file. */
var pushSocket=null,pushLive=false;
function pollDelay(){return pushLive?15000:2500}
function connectPush(){
  if(pushSocket||!game||game.status!=='active'||!window.WebSocket)return;
  try{pushSocket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws')}
  catch(e){pushSocket=null;return}
  pushSocket.addEventListener('open',function(){pushLive=true;startPoll()});
  pushSocket.addEventListener('message',function(ev){
    var data;try{data=JSON.parse(ev.data)}catch(e){return}
    if(!data||data.type!=='chess'||!game||data.id!==game.id)return;
    loadGame();
  });
  pushSocket.addEventListener('close',function(){pushSocket=null;pushLive=false;startPoll()});
  pushSocket.addEventListener('error',function(){pushLive=false});
}
function disconnectPush(){if(!pushSocket)return;try{pushSocket.close()}catch(e){}pushSocket=null;pushLive=false}
function startPoll(){clearTimeout(poll);if(document.hidden||!navigator.onLine)return;
if(game&&game.status==='active')connectPush();else disconnectPush();
poll=setTimeout(function tick(){(game?loadGame():loadMe()).finally(function(){
if(!document.hidden&&navigator.onLine&&((me&&me.queued)||(game&&((game.status==='active'&&game.turn!==game.side)||(game.status==='finished'&&game.rematchOffer==='mine')))))
poll=setTimeout(tick,pollDelay())})},pollDelay())}
